import * as THREE from 'three';

const TAU = Math.PI * 2;

/**
 * Builds the planet-system scene graph:
 *
 *   root (Group)
 *   └─ sun (Mesh, at origin)
 *   └─ planet pivot (Group, at origin, rotation.y animated)
 *      └─ planet mesh (positioned at x = orbitRadius)
 *         └─ moon pivot (Group, rotation.y animated)
 *            └─ moon mesh (positioned at x = orbitRadius)
 *
 * @param {Array<{name: string, orbitRadius: number, periodSec: number,
 *                moons?: Array<{name: string, orbitRadius: number, periodSec: number}>}>} planetSpecs
 */
export function createSystem(planetSpecs) {
  const root = new THREE.Group();
  const sun = new THREE.Mesh(new THREE.SphereGeometry(1, 16, 16));
  sun.name = 'sun';
  root.add(sun);

  const planets = planetSpecs.map((spec) => {
    const pivot = new THREE.Group();
    pivot.name = `${spec.name}-pivot`;
    const mesh = new THREE.Mesh(new THREE.SphereGeometry(0.5, 16, 16));
    mesh.name = spec.name;
    mesh.position.x = spec.orbitRadius;
    pivot.add(mesh);
    root.add(pivot);

    const moons = (spec.moons ?? []).map((moonSpec) => {
      const moonPivot = new THREE.Group();
      moonPivot.name = `${moonSpec.name}-pivot`;
      const moonMesh = new THREE.Mesh(new THREE.SphereGeometry(0.25, 12, 12));
      moonMesh.name = moonSpec.name;
      moonMesh.position.x = moonSpec.orbitRadius;
      moonPivot.add(moonMesh);
      mesh.add(moonPivot);
      return { spec: moonSpec, pivot: moonPivot, mesh: moonMesh };
    });

    return { spec, pivot, mesh, moons };
  });

  return { root, sun, planets };
}

/**
 * Advances the animation to absolute time tSec by setting each pivot's
 * rotation.y directly from t — pure function of time, so calling it with the
 * same t twice yields identical state (idempotent).
 *
 * Handedness convention: positive rotation.y in three.js rotates +x toward -z,
 * so a planet at x = orbitRadius orbits counterclockwise when viewed looking
 * down the +y axis.
 *
 * @param {ReturnType<typeof createSystem>} system
 * @param {number} tSec
 */
export function updateSystem(system, tSec) {
  for (const planet of system.planets) {
    planet.pivot.rotation.y = (TAU * tSec) / planet.spec.periodSec;
    for (const moon of planet.moons) {
      moon.pivot.rotation.y = (TAU * tSec) / moon.spec.periodSec;
    }
  }
}

