import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { createSystem, updateSystem } from '../src/system.js';

const TAU = Math.PI * 2;

const specs = [
  { name: 'Earth', orbitRadius: 10, periodSec: 8 },
  {
    name: 'Jupiter',
    orbitRadius: 20,
    periodSec: 12,
    moons: [{ name: 'Io', orbitRadius: 3, periodSec: 2 }],
  },
];

function worldPos(obj) {
  const v = new THREE.Vector3();
  obj.getWorldPosition(v);
  return v;
}

describe('createSystem / updateSystem', () => {
  it('places the sun at the origin', () => {
    const system = createSystem(specs);
    const p = worldPos(system.sun);
    expect(p.x).toBeCloseTo(0);
    expect(p.y).toBeCloseTo(0);
    expect(p.z).toBeCloseTo(0);
  });

  // Handedness pinned here: three.js positive rotation.y carries +x toward -z,
  // so Earth (x=10) after a quarter period (t=2 of 8) sits at (0, 0, -10).
  it('puts Earth at (0, 0, -10) at t=2', () => {
    const system = createSystem(specs);
    updateSystem(system, 2);
    const earth = system.planets.find((p) => p.spec.name === 'Earth').mesh;
    const p = worldPos(earth);
    expect(p.x).toBeCloseTo(0, 6);
    expect(p.y).toBeCloseTo(0, 6);
    expect(p.z).toBeCloseTo(-10, 6);
  });

  it('keeps |worldPos| == orbitRadius for 16 sampled times', () => {
    const system = createSystem(specs);
    const earth = system.planets.find((p) => p.spec.name === 'Earth');
    for (let i = 0; i < 16; i++) {
      const t = (i / 16) * earth.spec.periodSec;
      updateSystem(system, t);
      const d = worldPos(earth.mesh).length();
      expect(Math.abs(d - 10)).toBeLessThanOrEqual(1e-6);
    }
  });

  it('returns a moon with periodSec 2 to its t=0 world position at t=2', () => {
    const system = createSystem(specs);
    const jupiter = system.planets.find((p) => p.spec.name === 'Jupiter');
    const io = jupiter.moons[0];

    updateSystem(system, 0);
    const at0 = worldPos(io.mesh);

    updateSystem(system, 2);
    const at2 = worldPos(io.mesh);

    expect(at0.distanceTo(at2)).toBeLessThanOrEqual(1e-6);
  });

  it('updateSystem is idempotent for the same t', () => {
    const system = createSystem(specs);
    updateSystem(system, 3.5);
    const first = system.planets.map((p) => ({
      planet: p.pivot.rotation.y,
      moons: p.moons.map((m) => m.pivot.rotation.y),
    }));

    // extra calls, including interleaved other times, must not accumulate
    updateSystem(system, 99);
    updateSystem(system, 3.5);

    system.planets.forEach((p, i) => {
      expect(p.pivot.rotation.y).toBeCloseTo(first[i].planet, 12);
      p.moons.forEach((m, j) =>
        expect(m.pivot.rotation.y).toBeCloseTo(first[i].moons[j], 12)
      );
    });
  });

  it('matches closed-form angles: angle = 2*PI*t/period', () => {
    const system = createSystem(specs);
    const t = 5.25;
    updateSystem(system, t);
    for (const p of system.planets) {
      expect(((p.pivot.rotation.y % TAU) + TAU) % TAU).toBeCloseTo(
        ((TAU * t) / p.spec.periodSec) % TAU,
        12
      );
    }
  });
});

